package br.com.portalwifi

import android.content.Context
import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.Index
import androidx.room.Insert
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.Room
import androidx.room.RoomDatabase

/**
 * Local storage for future paid access. UUIDs are generated by the application
 * and can also be primary keys in a future Supabase/PostgreSQL schema.
 * A local row alone NEVER authorizes internet access: payment must be verified
 * on a trusted backend before the gateway grants access.
 */
@Entity(tableName = "access_sessions", indices = [Index(value = ["deviceId"]), Index(value = ["expiresAt"])])
data class AccessSession(
    @PrimaryKey val id: String,
    val deviceId: String,
    val createdAt: Long,
    val expiresAt: Long? = null,
    val state: String = "pending",
    val syncedAt: Long? = null
)

@Entity(tableName = "payment_records", indices = [Index(value = ["sessionId"]), Index(value = ["providerPaymentId"], unique = true)])
data class PaymentRecord(
    @PrimaryKey val id: String,
    val sessionId: String,
    val provider: String = "mercado_pago",
    val providerPaymentId: String? = null,
    val amountCents: Long,
    val currency: String = "BRL",
    val status: String = "pending",
    val createdAt: Long,
    val verifiedAt: Long? = null,
    val syncedAt: Long? = null
)

@Dao
interface PortalDao {
    @Insert suspend fun insertSession(session: AccessSession)
    @Insert suspend fun insertPayment(payment: PaymentRecord)
    @Query("SELECT * FROM access_sessions WHERE id = :id LIMIT 1")
    suspend fun session(id: String): AccessSession?
    @Query("SELECT * FROM payment_records WHERE sessionId = :sessionId ORDER BY createdAt DESC")
    suspend fun paymentsForSession(sessionId: String): List<PaymentRecord>
}

@Database(entities = [AccessSession::class, PaymentRecord::class], version = 1, exportSchema = false)
abstract class PortalDatabase : RoomDatabase() {
    abstract fun dao(): PortalDao

    companion object {
        @Volatile private var instance: PortalDatabase? = null
        fun get(context: Context): PortalDatabase =
            instance ?: synchronized(this) {
                instance ?: Room.databaseBuilder(
                    context.applicationContext,
                    PortalDatabase::class.java,
                    "portal-local.db"
                ).build().also { instance = it }
            }
    }
}
